def compute_order_amount(on_hand_inventory, pipeline_orders):
    # Core idea: pipeline-filling + feedback control (strictly stationary).
    # - During "startup" (pipeline not yet filled), behave close to a constant-order policy to avoid a huge first arrival.
    # - As the pipeline fills, gradually turn on feedback to maintain a target pipeline level and a modest on-hand buffer.

    base_order = 110.0  # OPT_PARAM: {"initial": 110.0, "min": 50.0, "max": 200.0, "type": "float"}
    safety_on_hand = 45.0  # OPT_PARAM: {"initial": 45.0, "min": 0.0, "max": 200.0, "type": "float"}

    k_inv = 0.60  # OPT_PARAM: {"initial": 0.60, "min": 0.0, "max": 2.0, "type": "float"}
    k_pipe = 0.25  # OPT_PARAM: {"initial": 0.25, "min": 0.0, "max": 2.0, "type": "float"}
    k_last = 0.35  # OPT_PARAM: {"initial": 0.35, "min": 0.0, "max": 2.0, "type": "float"}

    fill_threshold = 0.85  # OPT_PARAM: {"initial": 0.85, "min": 0.2, "max": 1.5, "type": "float"}
    startup_gain = 0.10  # OPT_PARAM: {"initial": 0.10, "min": 0.0, "max": 0.6, "type": "float"}

    deadband = 8.0  # OPT_PARAM: {"initial": 8.0, "min": 0.0, "max": 50.0, "type": "float"}
    order_cap = 450  # OPT_PARAM: {"initial": 450, "min": 50, "max": 1000, "type": "int"}

    # Defensive handling
    if pipeline_orders is None:
        pipeline_orders = []
    L = len(pipeline_orders)
    if L <= 0:
        x = base_order
        if x < 0:
            x = 0.0
        return int(round(x))

    pipe_sum = 0.0
    for q in pipeline_orders:
        pipe_sum += float(q)

    last = float(pipeline_orders[-1])

    # Pipeline "fullness" proxy: 0 => empty pipeline, 1 => roughly filled to L*base_order
    denom = fill_threshold * L * max(1.0, base_order)
    scale = pipe_sum / denom if denom > 1e-9 else 1.0
    if scale < 0.0:
        scale = 0.0
    elif scale > 1.0:
        scale = 1.0

    # Smoothly interpolate how much feedback is applied (startup -> steady)
    gain = startup_gain + (1.0 - startup_gain) * scale

    # Feedback signals
    err_inv = safety_on_hand - float(on_hand_inventory)          # keep on-hand around safety_on_hand
    err_pipe = (L * base_order) - pipe_sum                       # keep total pipeline near L*base_order
    err_last = base_order - last                                 # keep newest pipeline slot near base_order (shape/smooth)

    # Deadband to avoid jitter
    if err_inv < deadband and err_inv > -deadband:
        err_inv = 0.0
    if err_pipe < deadband and err_pipe > -deadband:
        err_pipe = 0.0
    if err_last < deadband and err_last > -deadband:
        err_last = 0.0

    # Main control law
    order = base_order + gain * (k_inv * err_inv + k_pipe * err_pipe + k_last * err_last)

    # Clamp and return integer
    if order < 0.0:
        order = 0.0
    if order > float(order_cap):
        order = float(order_cap)

    return int(round(order))

