def compute_order_amount(on_hand_inventory, pipeline_orders):
    # Pipeline-filling + risk-sensitive feedback (stationary; no time dependence).

    base_order = 120.0  # OPT_PARAM: {"initial": 120.0, "min": 0.0, "max": 600.0, "type": "float"}
    safety_buffer = 60.0  # OPT_PARAM: {"initial": 60.0, "min": 0.0, "max": 600.0, "type": "float"}

    k_avail = 0.65  # OPT_PARAM: {"initial": 0.65, "min": 0.0, "max": 2.0, "type": "float"}
    k_pipe = 0.25  # OPT_PARAM: {"initial": 0.25, "min": 0.0, "max": 2.0, "type": "float"}
    k_near = 0.40  # OPT_PARAM: {"initial": 0.40, "min": 0.0, "max": 2.0, "type": "float"}

    k_emerg = 0.60  # OPT_PARAM: {"initial": 0.60, "min": 0.0, "max": 5.0, "type": "float"}
    gamma = 1.20  # OPT_PARAM: {"initial": 1.20, "min": 1.0, "max": 2.0, "type": "float"}

    startup_gain = 0.05  # OPT_PARAM: {"initial": 0.05, "min": 0.0, "max": 0.5, "type": "float"}
    fill_threshold = 0.90  # OPT_PARAM: {"initial": 0.90, "min": 0.2, "max": 2.0, "type": "float"}

    order_cap = 1200.0  # OPT_PARAM: {"initial": 1200.0, "min": 100.0, "max": 2000.0, "type": "float"}

    if pipeline_orders is None:
        pipeline_orders = []

    L = len(pipeline_orders)
    if L <= 0:
        order_amount = base_order
        if order_amount < 0.0:
            order_amount = 0.0
        if order_amount > order_cap:
            order_amount = order_cap
        return order_amount

    # Core state features
    q1 = float(pipeline_orders[0])

    pipe_sum = 0.0
    for q in pipeline_orders:
        pipe_sum += float(q)

    available = float(on_hand_inventory) + q1

    # Near-term pipeline (shape control): ensure early arrivals are not starved
    k_slots = 2 if L >= 2 else 1
    near_sum = 0.0
    for j in range(k_slots):
        near_sum += float(pipeline_orders[j])

    # Smooth feedback activation: suppress aggressive "order-up-to" behavior when pipeline is empty
    denom = fill_threshold * float(L) * max(1.0, float(base_order))
    fullness = pipe_sum / denom if denom > 1e-9 else 1.0
    if fullness < 0.0:
        fullness = 0.0
    elif fullness > 1.0:
        fullness = 1.0
    gain = startup_gain + (1.0 - startup_gain) * fullness

    # Targets
    target_avail = base_order + safety_buffer
    target_pipe = float(L) * base_order
    target_near = float(k_slots) * base_order

    # Linear feedback terms
    err_avail = target_avail - available
    err_pipe = target_pipe - pipe_sum
    err_near = target_near - near_sum

    # Nonlinear emergency boost when immediate availability is critically low
    shortfall = safety_buffer - available
    if shortfall < 0.0:
        shortfall = 0.0
    emerg = gain * k_emerg * (shortfall ** gamma)

    # Control law
    order_amount = base_order + gain * (k_avail * err_avail + k_pipe * err_pipe + k_near * err_near) + emerg

    # Clamp
    if order_amount < 0.0:
        order_amount = 0.0
    if order_amount > order_cap:
        order_amount = order_cap

    return order_amount
